<?php

namespace ModulesGarden\TSSGGSModule\App\Libs;

/**
 * Inline SVG icons (Material Design Icons, path data in IconPaths.php, generated by tools/gen-icons.js).
 * The icon is a 24x24 viewBox drawn in the current text colour; its box is 16px unless the CSS of the place sets
 * another fixed size on .tssggs-ico.
 */
class Icons
{
    protected static $paths = null;

    /**
     * @param string $name icon name ("check", "mdi-check" and "mdi mdi-check" are all accepted)
     * @return string the <svg> element, '' for an unknown icon
     */
    public static function svg(string $name, string $class = ''): string
    {
        if(self::$paths === null)
        {
            self::$paths = require __DIR__ . '/IconPaths.php';
        }

        $name = preg_replace('/^.*\bmdi-/', '', trim($name));
        if(!isset(self::$paths[$name]))
        {
            return '';
        }

        return '<svg class="tssggs-ico tssggs-ico--' . $name . ($class !== '' ? ' ' . $class : '') . '" viewBox="0 0 24 24" width="16" height="16" aria-hidden="true" focusable="false">'
            . '<path fill="currentColor" d="' . self::$paths[$name] . '"/></svg>';
    }
}
